/**
 * Pushes any unsynced local task changes to Google Calendar and pulls
changes from Google Calendar back into the task list, reconciling by
stored Google event id. Uses an incremental sync token when available.

 * @summary Run a two-way sync between internal tasks and Google Calendar
 */
export const syncGoogleCalendar = async ( options?: RequestInit): Promise<GoogleSyncResult> => {

  return customFetch<GoogleSyncResult>(getSyncGoogleCalendarUrl(),
  {
    ...options,
    method: 'POST'


  }
);}




